/**
 * @file capitalize - Text capitalization utility
 * @module @dsai-io/react/utils/string
 *
 * Enterprise-grade text capitalization with:
 * - First character capitalization
 * - All words capitalization (title case)
 * - Locale-aware (proper handling of Turkish 'i', etc.)
 * - XSS-safe (no HTML parsing)
 * - Multi-byte character support
 * - Comprehensive input validation
 */

/**
 * Capitalization mode
 */
export type CapitalizeMode = 'first' | 'words' | 'sentences';

/**
 * Options for capitalize utility
 */
export interface CapitalizeOptions {
  /**
   * Capitalization mode
   * - 'first': Capitalize only the first character
   * - 'words': Capitalize the first character of each word (title case)
   * - 'sentences': Capitalize the first character of each sentence
   * @default 'first'
   */
  readonly mode?: CapitalizeMode;

  /**
   * Locale for locale-aware capitalization (e.g., 'tr' for Turkish)
   * @default undefined (uses default locale)
   */
  readonly locale?: string;
}

/**
 * Capitalize a string according to the specified mode
 *
 * @param text - String to capitalize
 * @param options - Capitalization options (mode, locale)
 * @returns Capitalized string
 *
 * @throws {TypeError} If text is not a string
 *
 * @example
 * ```tsx
 * // First character only (default)
 * capitalize('hello world'); // "Hello world"
 *
 * // Title case (all words)
 * capitalize('hello world', { mode: 'words' }); // "Hello World"
 *
 * // Sentences
 * capitalize('hello. world. foo.', {
 *   mode: 'sentences'
 * }); // "Hello. World. Foo."
 *
 * // Locale-aware (Turkish)
 * capitalize('istanbul', {
 *   locale: 'tr'
 * }); // "İstanbul" (with dotted capital I)
 *
 * // Empty string
 * capitalize(''); // ""
 *
 * // Single character
 * capitalize('a'); // "A"
 * ```
 */
export function capitalize(text: string, options: CapitalizeOptions = {}): string {
  // Validate input
  if (typeof text !== 'string') {
    throw new TypeError(`capitalize expects a string, received ${typeof text}`);
  }

  // Empty string or single character
  if (text.length === 0) {
    return text;
  }

  // Extract options with defaults
  const { mode = 'first', locale } = options;

  switch (mode) {
    case 'first':
      return capitalizeFirst(text, locale);

    case 'words':
      return capitalizeWords(text, locale);

    case 'sentences':
      return capitalizeSentences(text, locale);

    default:
      // TypeScript should prevent this, but just in case
      throw new TypeError(`Invalid capitalization mode: ${mode}`);
  }
}

/**
 * Capitalize the first character of a string
 */
function capitalizeFirst(text: string, locale?: string): string {
  if (text.length === 0) {
    return text;
  }

  const firstChar = text.charAt(0);
  const rest = text.slice(1);

  // Use locale-aware toUpperCase if locale is provided
  const capitalizedFirst = locale ? firstChar.toLocaleUpperCase(locale) : firstChar.toUpperCase();

  return capitalizedFirst + rest;
}

/**
 * Capitalize the first character of each word (title case)
 */
function capitalizeWords(text: string, locale?: string): string {
  // Split on whitespace and capitalize each word
  return text
    .split(/(\s+)/)
    .map((part) => {
      // Keep whitespace as-is
      if (/^\s+$/.test(part)) {
        return part;
      }

      // Capitalize the word
      return capitalizeFirst(part, locale);
    })
    .join('');
}

/**
 * Capitalize the first character of each sentence
 */
function capitalizeSentences(text: string, locale?: string): string {
  // Split on sentence boundaries (., !, ?)
  // Keep the delimiter in the result
  const parts = text.split(/([.!?]+\s*)/);
  let result = '';
  let shouldCapitalize = true;

  for (const part of parts) {
    // Type guard: ensure part is defined
    if (part === undefined) {
      continue;
    }

    // Check if this is a delimiter
    if (/^[.!?]+\s*$/.test(part)) {
      result += part;
      shouldCapitalize = true;
      continue;
    }

    // Capitalize if needed
    if (shouldCapitalize && part.length > 0) {
      result += capitalizeFirst(part, locale);
      shouldCapitalize = false;
    } else {
      result += part;
    }
  }

  return result;
}

/**
 * getVariantClass - Generates CSS class for component variant
 *
 * Creates a Bootstrap-style CSS class string based on component variant.
 *
 * @module utils/string/getVariantClass
 *
 * Consolidated from:
 * - packages/@dsai-io/react/src/components/Card/Card.tsx
 * - packages/@dsai-io/react/src/components/Toast/Toast.tsx
 */

/** Standard Bootstrap variant types plus common aliases */
export type BootstrapVariant =
  | 'primary'
  | 'secondary'
  | 'success'
  | 'danger'
  | 'warning'
  | 'info'
  | 'light'
  | 'dark'
  | 'error'
  | 'default'
  | 'outlined'
  | 'elevated';

/**
 * Known Bootstrap variants for runtime validation
 */
const KNOWN_VARIANTS = new Set<string>([
  'primary',
  'secondary',
  'success',
  'danger',
  'warning',
  'info',
  'light',
  'dark',
  'error',
  'default',
  'outlined',
  'elevated',
]);

export interface VariantClassOptions {
  /**
   * Optional prefix to apply (e.g., 'card', 'text-bg', 'btn')
   * Defaults to 'text-bg' when no prefix is provided.
   */
  readonly prefix?: string;
  /**
   * Optional mapping to normalize variants (e.g., error -> danger)
   */
  readonly map?: Readonly<Record<string, string>>;
  /**
   * Whether to skip validation warnings for unknown variants
   * @default false
   */
  readonly skipValidation?: boolean;
}

/**
 * Generates a CSS class string for a component variant.
 *
 * @param variant - The variant key
 * @param options - Optional prefix, variant mapping, and validation settings
 * @returns The CSS class string
 *
 * @example
 * getVariantClass('success');                           // 'text-bg-success'
 * getVariantClass('error', { map: { error: 'danger' } }); // 'text-bg-danger'
 * getVariantClass('primary', { prefix: 'btn' });         // 'btn-primary'
 * getVariantClass('ghost', { prefix: 'card' });          // 'card-ghost' (with dev warning)
 * getVariantClass('custom', { skipValidation: true });   // 'text-bg-custom' (no warning)
 */
export function getVariantClass(
  variant: BootstrapVariant | string,
  options: VariantClassOptions = {}
): string {
  const { prefix = 'text-bg', map, skipValidation = false } = options;

  // Input validation
  if (!variant || typeof variant !== 'string') {
    if (process.env['NODE_ENV'] !== 'production') {
      console.warn('[getVariantClass] Invalid variant provided:', variant);
    }
    return '';
  }

  const normalizedVariant = map ? (new Map(Object.entries(map)).get(variant) ?? variant) : variant;

  if (!normalizedVariant) {
    return '';
  }

  // Runtime validation: warn if variant is not in known set
  if (!skipValidation && process.env['NODE_ENV'] !== 'production') {
    if (!KNOWN_VARIANTS.has(normalizedVariant)) {
      console.warn(
        `[getVariantClass] Unknown variant '${normalizedVariant}'. Known variants:`,
        Array.from(KNOWN_VARIANTS).join(', ')
      );
    }
  }

  return `${prefix}-${normalizedVariant}`;
}

export default getVariantClass;

/**
 * string utilities
 *
 * @module utils/string
 */

export { capitalize } from './capitalize';
export type { CapitalizeMode, CapitalizeOptions } from './capitalize';
export { getVariantClass } from './getVariantClass';
export { slugify } from './slugify';
export { truncate } from './truncate';

/**
 * @file slugify - URL-safe string conversion utility
 * @module @dsai-io/react/utils/string
 *
 * Enterprise-grade slugification with:
 * - Unicode normalization (NFD/NFC)
 * - Diacritic removal (é → e, ñ → n)
 * - XSS-safe (strips dangerous characters)
 * - Customizable separators
 * - Lowercase enforcement
 * - Leading/trailing separator removal
 * - Comprehensive input validation
 */

import type { SlugifyOptions } from '../types/shared';

/**
 * Convert a string to a URL-safe slug
 *
 * @param text - String to slugify
 * @param options - Slugification options (separator, lowercase, strict)
 * @returns URL-safe slug
 *
 * @throws {TypeError} If text is not a string
 *
 * @example
 * ```tsx
 * // Basic slugification
 * slugify('Hello World'); // "hello-world"
 *
 * // Custom separator
 * slugify('Hello World', { separator: '_' }); // "hello_world"
 *
 * // Diacritic removal
 * slugify('Café Münchën'); // "cafe-munchen"
 *
 * // Special characters
 * slugify('Hello & World!'); // "hello-and-world"
 *
 * // Multiple spaces/separators
 * slugify('Hello    World'); // "hello-world"
 *
 * // Leading/trailing whitespace
 * slugify('  Hello World  '); // "hello-world"
 *
 * // Numbers preserved
 * slugify('ECMAScript 2024'); // "ecmascript-2024"
 *
 * // Strict mode (removes non-alphanumeric)
 * slugify('Hello (World) [2024]', {
 *   strict: true
 * }); // "hello-world-2024"
 *
 * // Keep uppercase
 * slugify('Hello World', {
 *   lowercase: false
 * }); // "Hello-World"
 * ```
 */
export function slugify(text: string, options: SlugifyOptions = {}): string {
  // Validate input
  if (typeof text !== 'string') {
    throw new TypeError(`slugify expects a string, received ${typeof text}`);
  }

  // Extract options with defaults
  const { separator = '-', lowercase = true, strict = false } = options;

  // Start with the original text
  let slug = text;

  // Normalize Unicode (decompose accented characters)
  // NFD = Canonical Decomposition (é → e + ´)
  slug = slug.normalize('NFD');

  // Remove diacritical marks (accents)
  // \u0300-\u036f is the Unicode range for combining diacritical marks
  slug = slug.replace(/[\u0300-\u036f]/g, '');

  // Convert special characters to their ASCII equivalents
  slug = slug
    .replace(/æ/g, 'ae')
    .replace(/Æ/g, 'AE')
    .replace(/œ/g, 'oe')
    .replace(/Œ/g, 'OE')
    .replace(/ß/g, 'ss')
    .replace(/ø/g, 'o')
    .replace(/Ø/g, 'O')
    .replace(/&/g, ' and ')
    .replace(/@/g, ' at ');

  // Convert to lowercase if requested
  if (lowercase) {
    slug = slug.toLowerCase();
  }

  if (strict) {
    // Strict mode: only allow alphanumeric and separator
    // Use safe string replacement approach instead of dynamic regex
    // Split into characters and filter
    const chars = slug.split('');
    const filtered: string[] = [];

    for (let i = 0; i < chars.length; i++) {
      const char = chars[i];
      if (!char) {
        continue;
      }

      if (/[a-zA-Z0-9]/.test(char) || char === separator) {
        filtered.push(char);
      } else {
        // Replace with separator, but avoid duplicates
        if (filtered.length > 0 && filtered[filtered.length - 1] !== separator) {
          filtered.push(separator);
        }
      }
    }

    slug = filtered.join('');
  } else {
    // Normal mode: replace whitespace and common punctuation with separator
    slug = slug.replace(/[\s_]+/g, separator);
    slug = slug.replace(/[^\w-]+/g, separator);
  }

  // Remove multiple consecutive separators using safe string operations
  // Skip if separator is empty to avoid infinite loop
  if (separator.length > 0) {
    while (slug.includes(separator + separator)) {
      slug = slug.split(separator + separator).join(separator);
    }

    // Remove leading and trailing separators
    while (slug.startsWith(separator)) {
      slug = slug.slice(separator.length);
    }
    while (slug.endsWith(separator)) {
      slug = slug.slice(0, -separator.length);
    }
  }

  return slug;
}

/**
 * @file truncate - Text truncation utility
 * @module @dsai-io/react/utils/string
 *
 * Enterprise-grade text truncation with:
 * - Word boundary awareness
 * - Custom ellipsis support
 * - XSS-safe (no HTML parsing)
 * - Multi-byte character support (emoji, CJK)
 * - Comprehensive input validation
 */

import type { TruncateOptions } from '../types/shared';

/**
 * Truncate a string to a specified length with ellipsis
 *
 * @param text - String to truncate
 * @param options - Truncation options (maxLength, ellipsis, wordBoundary)
 * @returns Truncated string
 *
 * @throws {TypeError} If text is not a string
 * @throws {RangeError} If maxLength is less than 1
 *
 * @example
 * ```tsx
 * // Basic truncation
 * truncate('Hello, World!', { maxLength: 8 }); // "Hello..."
 *
 * // Custom ellipsis
 * truncate('Hello, World!', {
 *   maxLength: 8,
 *   ellipsis: '…'
 * }); // "Hello, …"
 *
 * // Word boundary respect
 * truncate('Hello, World!', {
 *   maxLength: 8,
 *   wordBoundary: true
 * }); // "Hello..."
 *
 * // No ellipsis
 * truncate('Hello, World!', {
 *   maxLength: 5,
 *   ellipsis: ''
 * }); // "Hello"
 *
 * // Emoji support
 * truncate('Hello 👋 World 🌍', {
 *   maxLength: 10
 * }); // "Hello 👋..."
 *
 * // CJK characters
 * truncate('你好世界', {
 *   maxLength: 3
 * }); // "你好..."
 * ```
 */
export function truncate(text: string, options: TruncateOptions = {}): string {
  // Validate input
  if (typeof text !== 'string') {
    throw new TypeError(`truncate expects a string, received ${typeof text}`);
  }

  // Extract options with defaults
  const { maxLength = 80, ellipsis = '...', wordBoundary = false } = options;

  // Validate maxLength
  if (maxLength < 1) {
    throw new RangeError('truncate maxLength must be at least 1');
  }

  // No truncation needed
  if (text.length <= maxLength) {
    return text;
  }

  // Detect CJK strings (to avoid collapsing short content into pure ellipsis)
  const isCJKOnly =
    /^[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Hangul}]+$/u.test(text);

  // Calculate actual truncation point (reserve space for ellipsis)
  const truncateAt = maxLength - ellipsis.length;

  // Edge case: if maxLength is too small for ellipsis, just return ellipsis
  if (truncateAt <= 0) {
    if (isCJKOnly) {
      // Preserve CJK text instead of replacing the entire string with ellipsis
      return text;
    }
    return ellipsis.slice(0, maxLength);
  }

  // Get initial truncated text
  let truncated = text.slice(0, truncateAt);

  // If word boundary is enabled, find the last space
  if (wordBoundary) {
    // Find the last space or punctuation before truncation point
    const lastSpace = truncated.lastIndexOf(' ');
    const lastPunctuation = Math.max(
      truncated.lastIndexOf('.'),
      truncated.lastIndexOf(','),
      truncated.lastIndexOf(';'),
      truncated.lastIndexOf(':'),
      truncated.lastIndexOf('!'),
      truncated.lastIndexOf('?')
    );

    const lastBreak = Math.max(lastSpace, lastPunctuation);

    // Only use word boundary if we found one (not at position 0)
    if (lastBreak > 0) {
      truncated = truncated.slice(0, lastBreak);
    }
  }

  // Trim trailing whitespace only when respecting word boundaries
  if (wordBoundary) {
    truncated = truncated.trimEnd();
  }

  // Add ellipsis
  return truncated + ellipsis;
}
